1. LIMPIEZA
  
DROP TABLE IF EXISTS clientes;
DROP TABLE IF EXISTS productos;
DROP TABLE IF EXISTS pedidos;

-----------------------------------------------

2.CREACION DE LA BD Y SCHEMA

CREATE database cpastone_proyect;

CREATE SCHEMA IF NOT EXISTS capstone_EDA;

-----------------------------------------------

3.CREACION DE  LAS 3 TABLAS

CREATE TABLE capstone_EDA.clientes (
    cliente_id SERIAL PRIMARY KEY,
    nombre VARCHAR(50)  NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    ciudad VARCHAR (80) NOT NULL,
    fecha_registro DATE NOT NULL
);

CREATE TABLE capstone_EDA.productos (
    producto_id SERIAL PRIMARY KEY,
    nombre VARCHAR(80)   NOT NULL,
    categoria VARCHAR(40)   NOT NULL,
    precio_lista NUMERIC(10,2) NOT NULL CHECK (precio_lista > 0)
);

CREATE TABLE capstone_EDA.pedidos (
    pedido_id INTEGER PRIMARY KEY,
    cliente_id INTEGER NOT NULL REFERENCES clientes(cliente_id),
    producto_id INTEGER NOT NULL REFERENCES productos(producto_id),
    fecha_pedido DATE,
    cantidad INTEGER NOT NULL CHECK (cantidad > 0),
    precio_unitario NUMERIC(10,2) CHECK (precio_unitario > 0)
);

-----------------------------------------------

